lemma integrable_exp_neg_of_ae_eq {Ω : Type*} [MeasurableSpace Ω] {μ : Measure Ω}
    [IsFiniteMeasure μ] {X Y : Ω → ℝ} (hXY : X =ᵐ[μ] Y) (hY : Measurable Y) {B : ℝ}
    (hB : ∀ ω, |Y ω| ≤ B) (t : ℝ) :
    Integrable (fun ω => Real.exp (-t * X ω)) μ

lemma inUnit_of_noGrid {b : ℕ} {P : Fin n → ℝ × ℝ}
    (hP : ∀ i, (P i).1 ∈ Set.Icc (0 : ℝ) 1 ∧ (P i).2 ∈ Set.Icc (0 : ℝ) 1)
    (hgrid : NoGrid b P) : InUnit P

lemma measurable_stepFn_comp {α : Type*} [MeasurableSpace α] {V c : α → Fin n → ℝ} {y : α → ℝ}
    (hV : Measurable V) (hc : Measurable c) (hy : Measurable y) :
    Measurable (fun a => stepFn (V a) (c a) (y a))

theorem measurable_osc_Ico_stepFn_comp {α : Type*} [MeasurableSpace α] {V c : α → Fin n → ℝ}
    (hV : Measurable V) (hc : Measurable c) {s t : ℝ} (hst : s < t) :
    Measurable (fun a => osc (Set.Ico s t) (stepFn (V a) (c a)))

lemma integral_abs_add_eq_integral_abs_sub {X : Ω → ℝ}
    (hsymm : IdentDistrib X (fun ω => -X ω) μ μ) (θ : ℝ) :
    ∫ ω, |θ + X ω| ∂μ = ∫ ω, |θ - X ω| ∂μ

lemma integral_abs_le_integral_abs_add_of_symm [IsFiniteMeasure μ] {X : Ω → ℝ}
    (hsymm : IdentDistrib X (fun ω => -X ω) μ μ) (hX : Integrable X μ) (θ : ℝ) :
    ∫ ω, |X ω| ∂μ ≤ ∫ ω, |θ + X ω| ∂μ

lemma integrable_pow_of_integrable_pow_four [IsFiniteMeasure μ] {Y : Ω → ℝ}
    (hY : AEMeasurable Y μ) (h4 : Integrable (fun ω => Y ω ^ 4) μ) {k : ℕ} (hk : k ≤ 4) :
    Integrable (fun ω => Y ω ^ k) μ

lemma gridIndex_eq_idxOfDigits {b : ℕ} (hb : 0 < b) (j : ℕ) {u : ℝ}
    (hu : u ∈ Set.Ioc (0 : ℝ) 1) (hgrid : ∀ (m : ℤ) (r : ℕ), u ≠ (m : ℝ) / (b : ℝ) ^ r) :
    gridIndex (b ^ j) u = idxOfDigits b j (fun k => digit b ((k : ℕ) + 1) u)

theorem exists_symm_perm_iff (x : D → ℝ) :
    (∃ φ : D ≃ D, ∀ d, x (φ d) = -x d) ↔
      ∀ v : ℝ, Nat.card {d // x d = v} = Nat.card {d // x d = -v}

lemma mem_innerRegion_iff_of_noGrid {b : ℕ} (h j c v : ℕ) {P : Fin n → ℝ × ℝ}
    (hP : NoGrid b P) (i : Fin n) :
    P i ∈ innerRegion b h j c v ↔ P i ∈ innerRegionIoc b h j c v

lemma le_supNorm (χ : Fin n → ℤˣ) (P : Fin n → ℝ × ℝ) {x y : ℝ}
    (hx : x ∈ Set.Icc (0 : ℝ) 1) (hy : y ∈ Set.Icc (0 : ℝ) 1) :
    |F χ P x y| ≤ supNorm χ P

lemma childAvg_congr {b : ℕ} (ε V : Fin n → ℝ) (side : Fin n → Side) {r r' : Fin n → Fin b}
    (h : ∀ i, side i = Side.inside → r i = r' i) (k : Fin b) :
    childAvg ε V side r k = childAvg ε V side r' k

lemma innerRegion_inj {b h j : ℕ} (hb : 0 < b) {z : ℝ × ℝ}
    (hz : ∀ k : ℕ, z.1 ≠ (k : ℝ) / (b : ℝ) ^ j) {c c' v v' : ℕ}
    (h1 : z ∈ innerRegion b h j c v) (h2 : z ∈ innerRegion b h j c' v') : c = c' ∧ v = v'

lemma exists_card_eq_ceil_half {W : Set (ℝ × ℝ)} {P : Fin n → ℝ × ℝ}
    (hE : (n : ℝ) / 2 ≤ (Finset.univ.filter (fun i => P i ∈ W)).card) :
    ∃ T : Finset (Fin n), T.card = ⌈(n : ℝ) / 2⌉₊ ∧ ∀ i ∈ T, P i ∈ W

theorem mem_crowdEvent_heavySet {b h j : ℕ} (hb : 0 < b) (hj : j < h) {P : Fin n → ℝ × ℝ}
    (hP : ∀ i, (P i).1 ∈ Set.Icc (0 : ℝ) 1 ∧ (P i).2 ∈ Set.Ico (0 : ℝ) 1)
    (hbad : ¬ GoodTransition b h j P) : P ∈ crowdEvent b h j (heavySet b h j P)

lemma measurableSet_distinct_Icc_forall_lt_supNorm {n : ℕ} (t : ℝ) :
    MeasurableSet {P : Fin n → ℝ × ℝ | (∀ i j, i ≠ j → P i ≠ P j) ∧
      (∀ i, P i ∈ Set.Icc (0 : ℝ × ℝ) 1) ∧ ∀ χ : Fin n → ℤˣ, t < supNorm χ P}

theorem theorem_1_1_constant {A : ℝ} (hA : 0 < A) {b : ℕ}
    (hb1 : A + 2 ≤ Real.log ((b : ℝ) / 48) / 2) (hb2 : A + 2 + Real.log 2 ≤ (b : ℝ) / 4096)
    {n : ℕ} (hn : 1 ≤ n) :
    ENNReal.ofReal (1 - Real.exp (-A * n)) ≤
      unifPts n {P | ∀ χ : Fin n → ℤˣ, cA b * Real.logb 2 n ^ (3 / 2 : ℝ) ≤ supNorm χ P}

lemma integrable_of_abs_sub_le {α : Type*} [MeasurableSpace α] {μ : Measure α}
    [IsFiniteMeasure μ] {f : α → ℝ} (hf : Measurable f) {d : ℝ}
    (hosc : ∀ x y, |f x - f y| ≤ d) : Integrable f μ

lemma integrable_exp_of_abs_sub_le {α : Type*} [MeasurableSpace α] {μ : Measure α}
    [IsFiniteMeasure μ] {f : α → ℝ} (hf : Measurable f) {d : ℝ}
    (hosc : ∀ x y, |f x - f y| ≤ d) (t m : ℝ) :
    Integrable (fun x => Real.exp (t * (f x - m))) μ

lemma abs_integral_sub_integral_le {α : Type*} [MeasurableSpace α] {μ : Measure α}
    [IsProbabilityMeasure μ] {u v : α → ℝ} (hu : Integrable u μ) (hv : Integrable v μ) {d : ℝ}
    (h : ∀ a, |u a - v a| ≤ d) : |∫ a, u a ∂μ - ∫ a, v a ∂μ| ≤ d

lemma abs_sub_integral_le {α : Type*} [MeasurableSpace α] {μ : Measure α}
    [IsProbabilityMeasure μ] {f : α → ℝ} (hf : Integrable f μ) {d : ℝ}
    (hosc : ∀ x y, |f x - f y| ≤ d) (x : α) : |f x - ∫ y, f y ∂μ| ≤ d

theorem condExp_exp_le_cosh {Ω : Type*} {m m0 : MeasurableSpace Ω} {μ : Measure Ω}
    [IsProbabilityMeasure μ] (hm : m ≤ m0) {Y : Ω → ℝ} (hY : Measurable Y) {c : ℝ}
    (hc : 0 < c) (hbd : ∀ ω, |Y ω| ≤ c) (hmean : μ[Y | m] =ᵐ[μ] 0) (t : ℝ) :
    ∀ᵐ ω ∂μ, (μ[fun ω => Real.exp (t * Y ω) | m]) ω ≤ Real.cosh (t * c)

theorem condExp_exp_le_exp_sq {Ω : Type*} {m m0 : MeasurableSpace Ω} {μ : Measure Ω}
    [IsProbabilityMeasure μ] (hm : m ≤ m0) {Y : Ω → ℝ} (hY : Measurable Y) {c : ℝ}
    (hc : 0 < c) (hbd : ∀ ω, |Y ω| ≤ c) (hmean : μ[Y | m] =ᵐ[μ] 0) (t : ℝ) :
    ∀ᵐ ω ∂μ, (μ[fun ω => Real.exp (t * Y ω) | m]) ω ≤ Real.exp (t ^ 2 * c ^ 2 / 2)

lemma abs_sub_le_of_bounded_differences {E : Type*} {n : ℕ} (g : (Fin n → E) → ℝ) {c : ℝ}
    (hdiff : ∀ x i a, |g (Function.update x i a) - g x| ≤ c) (x y : Fin n → E) :
    |g x - g y| ≤ n * c

lemma osc_stepFn_single_le (V d : Fin n → ℝ) (i : Fin n) (hd : ∀ k, k ≠ i → d k = 0) {s t : ℝ}
    (hst : s < t) :
    osc (Set.Ico s t) (stepFn V d) ≤ if V i ∈ Set.Ico s t then |d i| else 0

lemma refineIdx_update_of_ne {b : ℕ} (g : Fin n → ℤ) (r : Fin n → Fin b) {i k : Fin n}
    (hk : k ≠ i) (a : Fin b) :
    refineIdx g (Function.update r i a) k = refineIdx g r k

lemma finiteGridIndex_lt_iff {K : ℕ} (hK : 0 < K) {x : ℝ}
    (hx : x ∈ Set.Ioc (0 : ℝ) 1) (s : ℕ) :
    (finiteGridIndex K hK x).val < s ↔ x ≤ (s : ℝ) / K

lemma direct_density {b : ℝ} (hb : 128 ≤ b) {n k : ℕ}
    (hk : Admissible b n k) (hmax : ∀ m, Admissible b n m → m ≤ k) :
    (n:ℝ) ≤ (k+1:ℝ)*b^k/(64*b^3)

lemma point_event_eq_coordinate_event {n : ℕ} (S : Set (Fin n → ℝ × ℝ)) :
    pointSampleLaw n S = ((coordinateSampleLaw n).prod (coordinateSampleLaw n))
      {UV | (fun i => (UV.1 i, UV.2 i)) ∈ S}

lemma density_bound {b : ℝ} (hb : 8 ≤ b) {n k : ℕ}
    (hk : Admissible b n k) (hmax : ∀ m, Admissible b n m → m ≤ k) :
    (n : ℝ) ≤ (k + 1 : ℝ) * b ^ k / (4 * b ^ 3)

lemma failure_exponent {A : ℝ} (hA : 0 < A) {L : ℕ}
    (hL : 4 * (A + 5) ≤ (L : ℝ)) :
    A + Real.log 2 ≤ Real.log ((2 : ℝ) ^ L) / 2 - 2 * Real.log 2 - 5 / 4

lemma coordinateOscillation_finAvg_last {n : ℕ} (f : (Fin (n + 1) → α) → ℝ) {d : ℝ}
    (hf : CoordinateOscillation f d) :
    CoordinateOscillation (fun x : Fin n → α ↦ finAvg (fun a ↦ f (Fin.snoc x a))) d

lemma lt_rectDisc {X : Finset (ℝ × ℝ)} {k : ℝ}
    (h : ∀ χ : X → ℤˣ, ∃ a b : ℝ × ℝ, k < |(colorSum X χ (Set.Icc a b) : ℝ)|) :
    k < rectDisc X

lemma card_eq_sum_fiber_card {ι κ : Type*} [Fintype ι] [Fintype κ]
    [DecidableEq κ] (a : ι → κ) :
    Fintype.card ι = ∑ c : κ, Fintype.card {i : ι // a i = c}

theorem condExp_ae_eq_dyadicMean (r : ℕ) {f : ℝ → ℝ}
    (hf : Integrable f μI) :
    μI[f | gridSigma (2 ^ r)] =ᵐ[μI] gridMean f (2 ^ r)

theorem condExp_sub_gridMean (n : ℕ) (hn : 0 < n) {f : ℝ → ℝ}
    (hf : Integrable f μI) :
    μI[(f - gridMean f n) | gridSigma n] =ᵐ[μI] 0
